def solve(g):
 h=len(g); w=len(g[0])
 counts={}
 for row in g:
  for x in row:
   counts[x]=counts.get(x,0)+1
 background=max(counts, key=counts.get)
 colors=[x for x in counts if x not in (0,background)]
 if len(colors)!=1:
  raise ValueError((background,colors))
 color=colors[0]
 points=[(r,c) for r,row in enumerate(g) for c,x in enumerate(row) if x==color]
 minr=min(r for r,c in points); minc=min(c for r,c in points)
 shape=[(r-minr,c-minc) for r,c in points]
 maxr=max(r for r,c in shape); maxc=max(c for r,c in shape)
 out=[row[:] for row in g]
 for r in range(h-maxr):
  for c in range(w-maxc):
   if all(g[r+dr][c+dc]==0 for dr,dc in shape):
    for dr,dc in shape:out[r+dr][c+dc]=color
 return out
